<style>
:root{font-family:system-ui,sans-serif;color:#172b3a;background:#f4f7fa}*{box-sizing:border-box}body{margin:0}main{max-width:1000px;margin:36px auto;padding:0 20px}nav{display:flex;gap:18px;flex-wrap:wrap;margin-bottom:25px}a{color:#145f9b}h1{font-size:28px}h2{font-size:20px}section,.card{background:white;padding:24px;border:1px solid #dbe3ea;border-radius:12px;margin:18px 0}label{display:block;font-weight:600;margin:16px 0 6px}input,textarea,select{font:inherit;max-width:100%;padding:10px;border:1px solid #aab9c6;border-radius:6px}input:not([type=hidden]),textarea{width:100%}button{font:inherit;cursor:pointer;border:0;background:#185f87;color:white;padding:11px 18px;border-radius:6px;margin:12px 6px 0 0}button.secondary{background:#526473}.notice{background:#e6f4ed;padding:14px;border-radius:6px}.errors{background:#fdecec;padding:14px;border-radius:6px;color:#8b2222}small,.muted{color:#596b7a}.row{display:flex;gap:15px;flex-wrap:wrap}.row>*{flex:1;min-width:200px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;line-height:1.7}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%}th,td{padding:12px 8px;border-bottom:1px solid #e1e8ed;text-align:left;white-space:nowrap}.badge{display:inline-block;background:#e5edf4;border-radius:4px;padding:4px 8px}fieldset{border:1px solid #dbe3ea;margin:12px 0;border-radius:6px}dl{display:grid;grid-template-columns:140px 1fr;gap:10px}dd{margin:0;overflow-wrap:anywhere}:focus-visible{outline:3px solid #eeac38;outline-offset:3px}
button:disabled{opacity:.5;cursor:not-allowed}
.password-field{position:relative}.password-field input{padding-right:52px}.password-field input::-ms-reveal{display:none}
.password-toggle{position:absolute;right:4px;top:50%;transform:translateY(-50%);margin:0;padding:10px;background:transparent;color:#526473;line-height:0}
.password-toggle[hidden],.password-toggle .password-eye-off{display:none}.password-toggle[aria-pressed=true] .password-eye{display:none}.password-toggle[aria-pressed=true] .password-eye-off{display:block}
</style>
